<?php require '_auth.php';if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM products WHERE id=?")->execute([(int)$_GET['delete']]);header('Location:products.php');exit;}$adminTitle='Products';$products=$pdo->query("SELECT * FROM products ORDER BY id DESC")->fetchAll();include '_header.php';?><section class="panel"><div class="panel-head"><h2>Product catalogue</h2><a class="btn" href="product_form.php">+ Add product</a></div><table class="table"><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td><img class="thumb" src="../<?=e($p['image'])?>"></td><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td>LKR <?=number_format($p['price'],2)?></td><td><?=$p['stock']?></td><td><span class="status"><?=e($p['status'])?></span></td><td><a class="btn gray" href="product_form.php?id=<?=$p['id']?>">Edit</a> <a class="btn red" onclick="return confirm('Delete product?')" href="products.php?delete=<?=$p['id']?>">Delete</a></td></tr><?php endforeach;?></table></section><?php include '_footer.php';?>
